// Simula una BD con lista en memoria para poder ejecutar
using Microsoft.EntityFrameworkCore;
using System.Collections.Generic;
using System;

public class Persona
{
    public int Id { get; set; }
    public string Nombre { get; set; }
    public string Apellido { get; set; }
}

public class MiDbContext
{
    public List<Persona> Personas { get; set; }
    public MiDbContext()
    {
        Personas = new List<Persona>();
    }
}

class Program
{
    static void Main(string[] args)
    {
        MiDbContext contexto = new MiDbContext();
        contexto.Personas.Add(new Persona { Id = 1, Nombre = "Juan", Apellido = "Pérez" });
        contexto.Personas.Add(new Persona { Id = 2, Nombre = "María", Apellido = "Gómez" });
        foreach (var persona in contexto.Personas)
        {
            Console.WriteLine(persona.Nombre + " " + persona.Apellido);
        }
    }
}
